            </summary>
            <div class="status-details-wrapper">
                <div class="status-item">
                    <strong>Sanity:</strong> <span class="sanity-value">$2</span>
                </div>
                <div class="status-item">
                    <strong>Status:</strong>
                    <ul class="status-list">
                         <!-- JS will populate this -->
                    </ul>
                    <pre id="raw-status-text" style="display: none;">$3</pre>
                </div>
                <div class="status-item">
                     <strong>Emotion:</strong> <span class="emotion-value">$4</span>
                </div>
                <div class="status-item">
                     <strong>Location:</strong> <span class="location-value">$5</span>
                </div>
            </div>
        </details>
    </div>

    <script>
        const rawStatusTextElement = document.getElementById('raw-status-text');
        const statusListElement = document.querySelector('.status-summary .status-list');

        if (rawStatusTextElement && statusListElement) {
            const statusTextBlock = rawStatusTextElement.textContent.trim();
            statusListElement.innerHTML = '';
            if (statusTextBlock) {
                 const lines = statusTextBlock.split('\n')
                    .map(line => line.trim())
                    .filter(line => line.startsWith('- ') || line.startsWith('• ') || line.startsWith('* '));

                 lines.forEach(line => {
                     const itemText = line.substring(line.indexOf(' ') + 1).trim();
                     if (itemText) {
                        const li = document.createElement('li');
                        li.textContent = itemText;
                        statusListElement.appendChild(li);
                     }
                 });
            }
        }

        const detailsElement = document.querySelector('.status-summary');
        if (detailsElement) {
            const wrapper = detailsElement.querySelector('.status-details-wrapper');
            const summaryBar = detailsElement.querySelector('summary');

            if (wrapper && summaryBar) {
                if (detailsElement.hasAttribute('open')) {
                    wrapper.style.maxHeight = wrapper.scrollHeight + 'px';
                    wrapper.style.opacity = '1';
                } else {
                    wrapper.style.maxHeight = '0px';
                    wrapper.style.opacity = '0';
                }

                summaryBar.addEventListener('click', (event) => {
                    event.preventDefault(); 

                    if (detailsElement.hasAttribute('open')) {
                        wrapper.style.maxHeight = '0px';
                        wrapper.style.opacity = '0';
                        setTimeout(() => {
                            detailsElement.removeAttribute('open');
                        }, 400); 
                    } else {
                        detailsElement.setAttribute('open', '');
                        requestAnimationFrame(() => {
                             wrapper.style.maxHeight = wrapper.scrollHeight + 'px';
                             wrapper.style.opacity = '1';
                        });
                    }
                });
            }
        }
    </script>
</body>
