                button.className = 'location-button-romance';
                let icon = 'fa-school'; // 默认校园图标
                if (location.name.includes('教学楼') || location.name.includes('实验楼')) icon = 'fa-university'; // 大学的感觉
                else if (location.name.includes('图书馆')) icon = 'fa-book-heart'; // 带爱心的书
                else if (location.name.includes('体育馆') || location.name.includes('操场')) icon = 'fa-volleyball-ball'; // 青春活力的排球
                else if (location.name.includes('食堂') || location.name.includes('餐厅')) icon = 'fa-mug-hot'; // 热饮杯，约饭的感觉
                else if (location.name.includes('宿舍')) icon = 'fa-house-user'; // 家的感觉
                else if (location.name.includes('商业街') || location.name.includes('商店')) icon = 'fa-store';
                else if (location.name.includes('公园') || location.name.includes('花园') || location.name.includes('湖') || location.name.includes('天台') || location.name.includes('情人坡')) icon = 'fa-leaf'; // 自然/浪漫地点
                else if (location.name.includes('家') || location.name.includes('小区')) icon = 'fa-home';

                button.innerHTML = `<i class="fas ${icon}"></i> ${location.name}`;
                button.dataset.location = location.name;
                button.addEventListener('click', () => selectMainLocation(location));
                button.disabled = hasMoveBlock;
                button.classList.toggle('disabled', hasMoveBlock);
                mainLocationsContainer.appendChild(button);
            });
            document.getElementById('sub-locations').classList.add('hidden');
            document.getElementById('location-details').classList.add('hidden');
            confirmMoveBtn.disabled = true; // 初始禁用确认按钮
            confirmMoveBtn.classList.remove('active-pulse'); // 移除动画
        }

        function selectMainLocation(location) {
            if (hasMoveBlock) return;
            selectedMain = location;
            document.querySelectorAll('#main-locations .location-button-romance').forEach(btn => {
                btn.classList.toggle('selected', btn.dataset.location === location.name);
            });
            const subLocationsContainer = document.getElementById('sub-locations');
            subLocationsContainer.innerHTML = '';
            location.subLocations.forEach(subLocation => {
                const button = document.createElement('button');
                button.className = 'sub-location-button-romance';
                let icon = 'fa-map-marker-alt'; // 默认标记
                if (subLocation.name.includes('教室')) icon = 'fa-chalkboard-user'; // 带用户的黑板
                else if (subLocation.name.includes('办公室')) icon = 'fa-folder-open';
                else if (subLocation.name.includes('自习室') || subLocation.name.includes('阅览室')) icon = 'fa-book-open-reader';
                else if (subLocation.name.includes('篮球场')) icon = 'fa-basketball-ball';
                else if (subLocation.name.includes('跑道')) icon = 'fa-person-running';
                else if (subLocation.name.includes('看台') || subLocation.name.includes('长椅')) icon = 'fa-couch'; // 长椅/沙发图标
                else if (subLocation.name.includes('窗口') || subLocation.name.includes('柜台')) icon = 'fa-cash-register';
                else if (subLocation.name.includes('房间') || subLocation.name.includes('卧室')) icon = 'fa-bed';
                else if (subLocation.name.includes('客厅')) icon = 'fa-tv';
                else if (subLocation.name.includes('阳台')) icon = 'fa-cloud-sun'; // 晴天
                else if (subLocation.name.includes('便利店')) icon = 'fa-shopping-basket';
                else if (subLocation.name.includes('咖啡馆')) icon = 'fa-coffee';
                else if (subLocation.name.includes('电影院')) icon = 'fa-film';
                else if (subLocation.name.includes('游戏厅')) icon = 'fa-gamepad';
                else if (subLocation.name.includes('角落') || subLocation.name.includes('深处')) icon = 'fa-eye-slash'; // 隐蔽

                button.innerHTML = `<i class="fas ${icon}"></i> ${subLocation.name}`;
                button.dataset.sublocation = subLocation.name;
                button.addEventListener('click', () => selectSubLocation(subLocation));
                subLocationsContainer.appendChild(button);
            });
            subLocationsContainer.classList.remove('hidden');
            document.getElementById('location-details').classList.add('hidden');
            selectedSub = null; // 重置子地点选择
            confirmMoveBtn.disabled = true; // 禁用确认按钮
            confirmMoveBtn.classList.remove('active-pulse'); // 移除动画
        }

        function selectSubLocation(subLocation) {
            if (hasMoveBlock) return;
            selectedSub = subLocation;
            selectedCharacters = subLocation.characters;
            document.querySelectorAll('#sub-locations .sub-location-button-romance').forEach(btn => {
                btn.classList.toggle('selected', btn.dataset.sublocation === subLocation.name);
            });
            document.getElementById('selected-location').textContent = `${selectedMain.name} - ${subLocation.name}`;
            const charactersContainer = document.getElementById('location-characters');
            charactersContainer.innerHTML = '';
            if (subLocation.characters.length > 0) {
                subLocation.characters.forEach(character => {
                    const charElement = document.createElement('div');
                    charElement.className = 'character-item-romance';
                    let charIcon = 'fa-user-circle'; // 默认圆形用户
                    if (character === '林浩宇') charIcon = 'fa-male'; // 你的世界书角色
                    else if (character === '月') charIcon = 'fa-female'; // 你的世界书角色
                    // 添加悬停显示爱心的效果
                    charElement.innerHTML = `<i class="fas ${charIcon}"></i> ${character} <i class="fas fa-heart heart-icon"></i>`;
                    charactersContainer.appendChild(charElement);
                });
            } else {
                const noCharElement = document.createElement('div');
                noCharElement.className = 'character-item-romance empty';
                noCharElement.innerHTML = `<i class="far fa-comment-dots"></i> 这里好像很安静...`; // 更委婉
                charactersContainer.appendChild(noCharElement);
            }
            document.getElementById('location-details').classList.remove('hidden');
            confirmMoveBtn.disabled = false; // 启用确认按钮
            confirmMoveBtn.classList.add('active-pulse'); // 添加动画
        }

        function confirmMove() {
            if (hasMoveBlock || !selectedMain || !selectedSub) return;
            const locationName = `${selectedMain.name} - ${selectedSub.name}`;
            const characters = selectedCharacters.join('、');
            const confirmMessage = document.getElementById('confirm-message');
            if (characters) {
                confirmMessage.textContent = `要去 ${locationName} 找 ${characters} 吗？`; // 更直接浪漫
            } else {
                confirmMessage.textContent = `要去 ${locationName} 看看吗？说不定会有什么发现~`; // 带点期待感
            }
            document.getElementById('confirm-overlay').classList.remove('hidden');
        }

        function executeMove() {
            if (hasMoveBlock || !selectedMain || !selectedSub) return;
            const locationName = `${selectedMain.name} - ${selectedSub.name}`;
            const characters = selectedCharacters.join(',');
            let message = `*你决定去${locationName}看看。*`; // 温和的动作描述
            if (typeof triggerSlash === 'function') {
                try {
                    triggerSlash(`/send ${message} || /trigger`);
                } catch (e) { console.error("发送消息时出错:", e); alert("发送消息失败！"); }
            } else {
                console.log("移动命令(模拟):", message);
                alert(`移动请求(模拟): ${message}`);
            }
            document.getElementById('confirm-overlay').classList.add('hidden');
            resetSelection();
        }

        function resetSelection() {
            selectedMain = null;
            selectedSub = null;
            selectedCharacters = [];
            document.querySelectorAll('.location-button-romance, .sub-location-button-romance').forEach(btn => {
                btn.classList.remove('selected');
            });
            document.getElementById('sub-locations').classList.add('hidden');
            document.getElementById('location-details').classList.add('hidden');
            confirmMoveBtn.disabled = true; // 重置时禁用
            confirmMoveBtn.classList.remove('active-pulse'); // 移除动画
        }

        function processMapData() {
            const dataSource = document.getElementById('map-data-source');
            if (!dataSource) return;
            let mapText = dataSource.textContent || dataSource.innerText;
            // 尝试从父窗口获取数据逻辑 (保持不变)
            try { if (window.parent && window.parent !== window) { /* ... */ } } catch (e) { console.log("无法从父窗口获取数据:", e); }
            // 尝试从URL获取数据逻辑 (保持不变)
             try { const urlParams = new URLSearchParams(window.location.search); const urlData = urlParams.get('data'); if (urlData) { const decodedData = decodeURIComponent(urlData); if (decodedData.includes('[MOVEBLOCK:')) { mapText = decodedData; } } } catch (e) { console.log("无法从URL参数获取数据:", e); }

            // 使用更丰富的校园恋爱测试数据
            if (!mapText || !mapText.includes('[MOVEBLOCK:')) {
                console.log("使用校园恋爱风格测试数据");
                mapText = `[MOVEBLOCK:NO]
[教学区
- 高二(3)班教室: 林浩宇, 月, 同学A
- 图书馆三楼靠窗座位: 月, 学霸B
- 空教室:
- 天台入口: ]
[活动区
- 体育馆篮球场: 林浩宇, 篮球队友
- 操场跑道:
- 活动中心社团室: 同学C]
[生活区 & 校外
- 食堂二楼: 月, 闺蜜D
- 宿舍楼下长椅:
- 青春商业街奶茶店: 月
- 静思书店: 林浩宇]`;
                dataSource.textContent = mapText;
            }
            mapData = parseMapData(mapText);
            if (mapData) {
                renderMapInterface(mapData);
            } else {
                const mainLocationsContainer = document.getElementById('main-locations');
                mainLocationsContainer.innerHTML = '<p style="color: var(--romance-accent-red); text-align: center;">呜，地图好像迷路了...</p>';
            }
        }

        function setupEventListeners() {
            confirmMoveBtn.addEventListener('click', confirmMove); // 确认按钮
            document.getElementById('cancel-move-btn').addEventListener('click', () => {
                document.getElementById('confirm-overlay').classList.add('hidden');
            });
            document.getElementById('execute-move-btn').addEventListener('click', executeMove);
        }

        function init() {
            setupEventListeners();
            processMapData();
            // SillyTavern事件监听 (保持不变)
             if (window.parent && window.parent !== window && typeof window.parent.eventOn === 'function' && window.parent.tavern_events) {
                 const refreshMap = () => setTimeout(processMapData, 300);
                 window.parent.eventOn(window.parent.tavern_events.MESSAGE_UPDATED, refreshMap);
                 window.parent.eventOn(window.parent.tavern_events.MESSAGE_RECEIVED, refreshMap);
                 window.parent.eventOn(window.parent.tavern_events.CHAT_CHANGED, refreshMap);
             }
        }
        document.addEventListener('DOMContentLoaded', init);
    </script>

